// Saved job-site passwords: the encrypted vault, and making, filling and
// saving passwords on account pages through the service worker. Every
// password here is generated by the test or made up for it.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadPage, loadBackground, PROFILE } from './helpers.mjs';

const SITE = 'globex.wd5.myworkdayjobs.com';
const PASSPHRASE = 'test passphrase for jobu';
const CREATE = `<html><head><title>Create Account</title></head><body><form><h2>Create Account</h2>
  <label for="email">Email Address</label><input id="email" type="email">
  <label for="pw">Password</label><input id="pw" type="password">
  <label for="pw2">Verify New Password</label><input id="pw2" type="password">
  <button type="submit">Create Account</button></form></body></html>`;
const SIGN_IN = `<html><head><title>Sign In</title></head><body><form><h2>Sign In</h2>
  <label for="email">Email Address</label><input id="email" type="email">
  <label for="pw">Password</label><input id="pw" type="password">
  <button type="submit">Sign In</button></form></body></html>`;

function setup(html, { url = `https://${SITE}/en-US/careers/login`, storage = { profile: PROFILE }, session = {} } = {}) {
  const page = loadPage(html, { storage, url });
  const bg = loadBackground(page);
  Object.assign(bg.session, session);
  return { page, bg, d: page.document };
}

test('the vault encrypts, locks and only opens with the passphrase', async () => {
  const { bg, page } = setup(SIGN_IN);
  const vault = (code) => bg.run(`JOBU.vault.${code}`);
  assert.equal(await vault('status()'), 'none');
  await assert.rejects(vault("create('short')"), /at least 8/);
  await vault(`create(${JSON.stringify(PASSPHRASE)})`);
  assert.equal(await vault('status()'), 'unlocked');
  await vault(`save({ site: 'acme.icims.com', username: 'ada@example.com', password: 'made-up-Secret-1' })`);
  assert.equal((await vault("find('acme.icims.com')")).password, 'made-up-Secret-1');
  assert.ok(!JSON.stringify(page.store).includes('made-up-Secret-1'), 'stored encrypted');
  assert.deepEqual(page.store.vaultIndex.map((e) => [e.site, e.username]), [['acme.icims.com', 'ada@example.com']]);

  await vault('lock()');
  assert.equal(await vault('status()'), 'locked');
  await assert.rejects(vault("unlock('not the passphrase')"), /That passphrase is wrong/);
  await vault(`unlock(${JSON.stringify(PASSPHRASE)})`);
  assert.equal((await vault('entries()')).length, 1);
});

test('generated passwords are long, mixed and avoid look-alike characters', async () => {
  const { bg } = setup(SIGN_IN);
  const made = new Set();
  for (let i = 0; i < 50; i++) {
    const p = bg.run('JOBU.vault.generate()');
    assert.equal(p.length, 16);
    for (const re of [/[A-Z]/, /[a-z]/, /[2-9]/, /[!@#$%&*?_-]/]) assert.match(p, re);
    assert.doesNotMatch(p, /[0O1lI]/);
    made.add(p);
  }
  assert.equal(made.size, 50);
});

test('creates a password on a sign-up page, fills both boxes and saves it for the site', async () => {
  const { bg, d, page } = setup(CREATE);
  await bg.run(`JOBU.vault.create(${JSON.stringify(PASSPHRASE)})`);
  const scan = await bg.call({ type: 'SCAN_TAB' });
  assert.deepEqual({ kind: scan.account.kind, site: scan.account.site, vault: scan.account.vault, saved: scan.account.saved }, {
    kind: 'create', site: SITE, vault: 'unlocked', saved: [],
  });

  const r = await bg.call({ type: 'ACCOUNT_PASSWORD', op: 'create', frameId: 0 });
  assert.deepEqual(r, { action: 'password', op: 'create', done: true, site: SITE, username: 'ada@example.com' });
  const made = d.getElementById('pw').value;
  assert.equal(made.length, 16);
  assert.equal(d.getElementById('pw2').value, made);
  assert.equal(d.getElementById('email').value, 'ada@example.com');
  const saved = await bg.run(`JOBU.vault.find('${SITE}')`);
  assert.equal(saved.password, made);
  assert.equal(saved.label, 'Globex');

  // Later, on the same site's sign-in page: fills the saved one.
  const later = setup(SIGN_IN, { storage: page.store, session: bg.session });
  const filled = await later.bg.call({ type: 'ACCOUNT_PASSWORD', op: 'fill', frameId: 0 });
  assert.equal(filled.done, true);
  assert.equal(later.d.getElementById('pw').value, made);
  assert.equal(later.d.getElementById('email').value, 'ada@example.com');

  // Another site gets nothing, whatever its page says.
  const other = setup(SIGN_IN, { url: 'https://login.example.net/workday', storage: page.store, session: bg.session });
  const none = await other.bg.call({ type: 'ACCOUNT_PASSWORD', op: 'fill', frameId: 0 });
  assert.equal(none.none, true);
  assert.equal(other.d.getElementById('pw').value, '');
});

test('saves a password the user typed, and does nothing while locked', async () => {
  const { bg, d, page } = setup(SIGN_IN);
  await bg.run(`JOBU.vault.create(${JSON.stringify(PASSPHRASE)})`);
  d.getElementById('email').value = 'ada@example.com';
  d.getElementById('pw').value = 'typed-by-user-9';
  const r = await bg.call({ type: 'ACCOUNT_PASSWORD', op: 'save', frameId: 0 });
  assert.deepEqual(r, { action: 'password', op: 'save', done: true, site: SITE, username: 'ada@example.com' });
  assert.equal((await bg.run(`JOBU.vault.find('${SITE}', 'ada@example.com')`)).password, 'typed-by-user-9');

  const locked = setup(CREATE, { storage: page.store });
  assert.deepEqual(await locked.bg.call({ type: 'ACCOUNT_PASSWORD', op: 'create', frameId: 0 }), { action: 'password', op: 'create', vault: 'locked' });
  assert.equal(locked.d.getElementById('pw').value, '');
});
